#include "UI/UnmadePlayerFacingRules.h"
#include "UI/UnmadePlayerPreferences.h"
#include "GameFramework/InputSettings.h"
void UUnmadePlayerPreferences::Validate(){if(!GuardKey.IsValid())GuardKey=EKeys::RightMouseButton;if(!TechniqueKey.IsValid())TechniqueKey=EKeys::F11;if(!PadGuard.IsValid())PadGuard=EKeys::Gamepad_LeftTrigger;if(!PadTechnique.IsValid())PadTechnique=EKeys::Gamepad_LeftThumbstick;TextScale=FMath::IsFinite(TextScale)?FMath::Clamp(TextScale,.85f,1.6f):1;CameraSensitivity=FMath::IsFinite(CameraSensitivity)?FMath::Clamp(CameraSensitivity,.4f,2.f):1;AudioVolume=FMath::IsFinite(AudioVolume)?FMath::Clamp(AudioVolume,0.f,1.f):1;if(!AttackKey.IsValid())AttackKey=EKeys::LeftMouseButton;if(!DodgeKey.IsValid())DodgeKey=EKeys::LeftShift;if(!InteractKey.IsValid())InteractKey=EKeys::E;if(!PadAttack.IsValid())PadAttack=EKeys::Gamepad_RightTrigger;if(!PadDodge.IsValid())PadDodge=EKeys::Gamepad_FaceButton_Right;if(!PadInteract.IsValid())PadInteract=EKeys::Gamepad_FaceButton_Left;}
void UUnmadePlayerPreferences::ApplyMappings(){Validate();auto* inputs=UInputSettings::GetInputSettings();if(!inputs)return;const FName names[]={TEXT("Attack"),TEXT("DodgeStep"),TEXT("Interact"),TEXT("Guard"),TEXT("FieldTechnique")};const FKey keys[]={AttackKey,DodgeKey,InteractKey,GuardKey,TechniqueKey},pads[]={PadAttack,PadDodge,PadInteract,PadGuard,PadTechnique};TArray<FInputActionKeyMapping> previous=inputs->GetActionMappings();for(int n=0;n<5;++n){for(const auto& m:previous)if(m.ActionName==names[n])inputs->RemoveActionMapping(m,false);inputs->AddActionMapping(FInputActionKeyMapping(names[n],keys[n]),false);inputs->AddActionMapping(FInputActionKeyMapping(names[n],pads[n]),false);}inputs->ForceRebuildKeymaps();}
bool UUnmadePlayerPreferences::Bind(int action,FKey key,FString& reason){if(action<1||action>5||!key.IsValid()||key.IsAnalog()){reason=TEXT("Choose a button or keyboard key.");return false;}if(key==EKeys::Escape||key==EKeys::Tab||key==EKeys::J||key==EKeys::I||key==EKeys::W||key==EKeys::A||key==EKeys::S||key==EKeys::D){reason=TEXT("That key is reserved for movement or menus.");return false;}const FName names[]={TEXT("Attack"),TEXT("DodgeStep"),TEXT("Interact"),TEXT("Guard"),TEXT("FieldTechnique")};auto* inputs=UInputSettings::GetInputSettings();for(const auto& m:inputs->GetActionMappings())if(m.Key==key&&m.ActionName!=names[action-1]){reason=TEXT("That key already performs another action. Choose a free key.");return false;}if(key.IsGamepadKey()){if(action==1)PadAttack=key;if(action==2)PadDodge=key;if(action==3)PadInteract=key;if(action==4)PadGuard=key;if(action==5)PadTechnique=key;}else{if(action==1)AttackKey=key;if(action==2)DodgeKey=key;if(action==3)InteractKey=key;if(action==4)GuardKey=key;if(action==5)TechniqueKey=key;}ApplyMappings();SaveConfig();reason=TEXT("Control saved. Keyboard and controller bindings remain independent.");return true;}
FString UUnmadePlayerPreferences::Describe()const{return FString::Printf(TEXT("Text %.0f%% / camera %.0f%% / sound %.0f%%\nHigh contrast %s / reduced flashes %s / tutorials %s\nAttack: %s (%s)\nDodge: %s (%s)\nInteract: %s (%s)\nGuard: %s (%s)\nTechnique: %s (%s)\nChoose a rebind button, then press a free key, mouse button or controller button. Escape cancels. Gamepad shoulders change menu pages; B closes; A activates; D-pad navigates.\n"),TextScale*100,CameraSensitivity*100,AudioVolume*100,HighContrast?TEXT("on"):TEXT("off"),ReducedFlashes?TEXT("on"):TEXT("off"),ShowTutorials?TEXT("on"):TEXT("off"),*AttackKey.GetDisplayName().ToString(),*PadAttack.GetDisplayName().ToString(),*DodgeKey.GetDisplayName().ToString(),*PadDodge.GetDisplayName().ToString(),*InteractKey.GetDisplayName().ToString(),*PadInteract.GetDisplayName().ToString(),*GuardKey.GetDisplayName().ToString(),*PadGuard.GetDisplayName().ToString(),*TechniqueKey.GetDisplayName().ToString(),*PadTechnique.GetDisplayName().ToString());}
FString UUnmadePlayerPreferences::ControlPrompt()const{return ControllerPrompts?FString::Printf(TEXT("%s interact / %s attack / %s dodge / Menu journal / shoulders change pages"),*PadInteract.GetDisplayName().ToString(),*PadAttack.GetDisplayName().ToString(),*PadDodge.GetDisplayName().ToString()):FString::Printf(TEXT("%s interact / %s attack / %s dodge / J journal / I equipment / Tab map"),*InteractKey.GetDisplayName().ToString(),*AttackKey.GetDisplayName().ToString(),*DodgeKey.GetDisplayName().ToString());}
FString UUnmadePlayerPreferences::FormatControls(const FString& input)const{
 struct Label {const TCHAR* key;const TCHAR* action;};const Label labels[]={{TEXT("Left mouse"),TEXT("Attack")},{TEXT("Right mouse"),TEXT("Guard")},{TEXT("LMB"),TEXT("Attack")},{TEXT("RMB"),TEXT("Guard")},{TEXT("F11"),TEXT("FieldTechnique")},{TEXT("F12"),TEXT("RiteLaw")},{TEXT("F10"),TEXT("RiteBreak")},{TEXT("F9"),TEXT("EvidenceNotebook")},{TEXT("F8"),TEXT("FactionTruth")},{TEXT("F7"),TEXT("FactionSolidarity")},{TEXT("F6"),TEXT("RiteChoice2")},{TEXT("F5"),TEXT("RiteChoice1")},{TEXT("F4"),TEXT("RiteUse")},{TEXT("F3"),TEXT("RiteStudy")},{TEXT("F2"),TEXT("ConfluenceStudy")},{TEXT("F1"),TEXT("ConfluenceCycle")},{TEXT("Shift"),TEXT("DodgeStep")},{TEXT("Ctrl"),TEXT("Sneak")},{TEXT("Tab"),TEXT("WorldMap")},{TEXT("E"),TEXT("Interact")},{TEXT("F"),TEXT("AnomalyPulse")},{TEXT("Q"),TEXT("FoldReality")},{TEXT("R"),TEXT("RewriteOpen")},{TEXT("T"),TEXT("RewriteSealed")},{TEXT("G"),TEXT("FrontierTravel")},{TEXT("J"),TEXT("StoryJournal")},{TEXT("I"),TEXT("ItemInventory")}};
 FString result=input;result.ReplaceInline(TEXT("6 or 7 choose"),TEXT("use Choice A or Choice B in Actions"));result.ReplaceInline(TEXT("6:"),TEXT("Choice A:"));result.ReplaceInline(TEXT("7:"),TEXT("Choice B:"));
 auto* settings=UInputSettings::GetInputSettings();if(!settings)return result;
 std::vector<UnmadeCore::ControlLabel> resolved;
 for(const auto& item:labels){FString display=ControllerPrompts?FString(TEXT("Actions / "))+item.action:item.key;for(const auto& mapping:settings->GetActionMappings())if(mapping.ActionName==FName(item.action)&&mapping.Key.IsGamepadKey()==ControllerPrompts){display=mapping.Key.GetDisplayName().ToString();break;}resolved.push_back({TCHAR_TO_UTF8(item.key),TCHAR_TO_UTF8(*display)});}
 const auto formatted=UnmadeCore::FormatControlLabels(TCHAR_TO_UTF8(*result),resolved);result=UTF8_TO_TCHAR(formatted.c_str());
 return result;
}
